let resumeReport=null,resumeMode=workspaceSession.getItem('proof-selected-listing')?'job':'general';
function resumePage(){const hasResume=Boolean(savedResumeFile()||marketplaceResume().trim());return `<div class="review-page-heading"><div><span class="section-label">MY WORKSPACE / MY RESUME</span><h1>My resume</h1><p>Review your resume, or compare it with the work you want to do.</p></div>${resumeReport?'<a class="outline" href="#resume/results">Open latest results '+icon('arrow',16)+'</a>':''}</div><section class="review-composer"><div class="review-composer-toolbar"><div class="resume-flow-steps"><span class="current">${icon('resume',16)} My resume</span>${icon('arrow',14)}<span>Optional focus</span>${icon('arrow',14)}<span>Specific edits</span></div><span>${icon('lock',14)} Saved privately to your account</span></div><form id="resume-review-form"><div class="review-compose-grid ${resumeMode==='job'?'has-job':''}"><section class="review-source"><div class="review-section-heading"><h2>1. My resume</h2><button class="text-control" type="button" onclick="loadResumeExample()">Use example</button></div><label class="upload-zone compose-upload" id="resume-drop">${icon('resume',22)}<span><b>${hasResume?'Replace resume':'Upload resume'}</b><small>PDF, DOCX, TXT · up to 5 MB</small></span><input id="resume-file" type="file" aria-label="Upload resume" accept=".pdf,.docx,.txt"></label><div class="compose-file-status"><p id="file-status" class="resume-hint" role="status">${hasResume?'Your saved resume is ready to review.':'Drop a file above or paste your resume below.'}</p>${savedResumeFile()?'<details><summary>Saved file</summary>'+savedResumeHTML()+'</details>':''}</div><div id="resume-upload-progress" hidden></div>${savedResumeFile()?`<div id="review-resume-document" class="resume-document-view" aria-label="Your saved resume document"></div>`:`<div class="resume-document-empty"><p>Upload the original document to preview your resume and share it with organizations.</p></div>`}<details id="resume-matching-text" class="resume-matching-text"><summary>${savedResumeFile()?'Extracted text for matching':'Use pasted text for matching'}</summary><p class="resume-hint">This text supports matching and suggestions. It does not replace the original document shared with organizations.</p><label class="field">Resume text<textarea id="review-resume" maxlength="30000" placeholder="Paste your experience, education, projects, and skills here.">${esc(marketplaceResume())}</textarea></label></details><div class="compose-text-footer"><div class="resume-counter" id="resume-count"></div><button type="button" class="text-control" onclick="clearResume()">Clear resume</button></div></section><section class="review-target"><div class="review-section-heading"><h2>2. Review focus <span class="optional-label">Optional</span></h2></div><label class="field">Target job title or field (optional)<input id="review-job-title" data-search-catalog="roles" maxlength="150" placeholder="e.g. Frontend developer or Marketing" value="${esc(workspaceSession.getItem('proof-job-title')||'')}"></label><p class="resume-hint">Leave this blank for a general review. Add a role or field to focus the suggestions.</p><details id="job-fields" class="resume-target-details" ><summary>${getResumeListing()?'Opportunity selected · change comparison':'Compare a listing or job description'} ${icon('plus',15)}</summary><label class="field">Choose an opportunity<select id="review-listing" onchange="selectResumeListing(this.value)"><option value="">No listing selected</option>${jobs.map(j=>`<option value="${j.id}" ${workspaceSession.getItem('proof-selected-listing')===String(j.id)?'selected':''}>${esc(j.c)} · ${esc(j.title)}</option>`).join('')}</select></label><div id="selected-listing-summary">${listingSummary()}</div><label class="field">Job description (optional)<textarea id="review-job" maxlength="20000" placeholder="Paste the responsibilities and requirements for a more detailed comparison.">${esc(workspaceSession.getItem('proof-job')||'')}</textarea></label></details><div class="review-method-row"><label class="field">Review method<select id="review-method"><option value="local">Nextwork Match + instant review</option><option value="ai">Gemini writing review · free tier</option></select></label><p id="backend-status" class="resume-hint" role="status">Checking AI availability…</p></div><div id="ai-settings" hidden><p class="resume-hint">AI review sends your resume to Google Gemini. Free-tier content may be used to improve its products.</p></div></section></div><div class="review-submit-bar"><div><p id="review-error" class="review-error" role="alert"></p><span>Matching runs in your browser. <button type="button" class="match-model-tag" onclick="showNextworkModel()">About Nextwork Match</button></span></div><button class="primary" id="run-review">Review resume ${icon('arrow',17)}</button></div></form></section>`}
let resumeReviewState={busy:false,error:'',step:0};
function resumeResultsPage(){
 if(resumeReviewState.busy)return `<a class="text-link" href="#resume">${icon('arrow',15)} Back to resume</a><div id="resume-results">${loadingView('Reviewing your resume','Reading your experience and preparing feedback.',false,['Read your resume','Review the evidence','Prepare feedback'],resumeReviewState.step)}</div>`;
 if(resumeReviewState.error)return `<div class="review-results-top"><a class="text-link" href="#resume">Back to resume</a></div><section class="empty-state"><h1>Your review couldn’t finish</h1><p role="alert">${esc(resumeReviewState.error)}</p><a href="#resume" class="primary">Return to your resume ${icon('arrow',16)}</a></section>`;
 if(!resumeReport)return `<section class="empty-state"><h1>Your review starts with your resume</h1><p>Add your experience to see your feedback and job alignment.</p><a href="#resume" class="primary">Review your resume ${icon('arrow',16)}</a></section>`;
 return `<div class="review-results-top"><a class="text-link" href="#resume">${icon('resume',16)} Edit resume</a><div>${resumeReport.listingId?`<a class="outline" href="#project/${resumeReport.listingId}">View opportunity ${icon('arrow',16)}</a>`:''}<button class="outline" onclick="downloadResumeReport()">${icon('archive',16)} Download report</button></div></div><section id="resume-results" class="review-results-page" aria-live="polite">${reportHTML(resumeReport)}</section>`;
}

function setResumeMode(mode){saveResumeDraft();resetResumeReview();resumeMode=mode;render()}
function bindResume(){if(typeof ResumeDocuments!=='undefined')ResumeDocuments.paintReview();$('#review-resume').value=workspaceSession.getItem('proof-resume')||'';$('#review-job').value=workspaceSession.getItem('proof-job')||'';$('#review-job-title').value=workspaceSession.getItem('proof-job-title')||'';const selected=getResumeListing();if(selected){$('#review-job').value=listingDescription(selected);$('#review-job-title').value=selected.title;}$('#review-listing').disabled=false;$('#review-job').readOnly=Boolean(selected);$('#review-job-title').readOnly=Boolean(selected);$('#review-job').disabled=false;$('#review-job-title').disabled=false;const text=$('#review-resume');const count=()=>{setMarketplaceResume(text.value);$('#resume-count').textContent=`${text.value.trim()?text.value.trim().split(/\s+/).length:0} words · ${text.value.length.toLocaleString()}/30,000 characters`};count();text.oninput=()=>{const file=savedResumeFile();if(file&&text.value!==marketplaceResume()){file.textEdited=true;workspaceLocal.setItem('proof-resume-file',JSON.stringify(file));}count()};$('#resume-file').onchange=e=>readResumeFile(e.target.files[0]);const drop=$('#resume-drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');readResumeFile(e.dataTransfer.files[0])};$('#review-method').onchange=e=>{$('#ai-settings').hidden=e.target.value!=='ai'};$('#resume-review-form').onsubmit=runResumeReview;checkResumeBackend()}
async function parseResumeFile(file){if(file.size>5*1024*1024)throw Error('File is too large. Choose a file under 5 MB.');let text,ext=file.name.split('.').pop().toLowerCase();if(ext==='txt')text=await file.text();else if(ext==='pdf'){const pdf=await ResumeDocuments.pdf();const doc=await pdf.getDocument({data:await file.arrayBuffer(),isEvalSupported:false}).promise;if(doc.numPages>20)throw Error('Use a resume with 20 pages or fewer.');let pages=[];for(let i=1;i<=doc.numPages;i++){const page=await doc.getPage(i),content=await page.getTextContent();pages.push(content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join(''))}text=pages.join('\n');await doc.destroy()}else if(ext==='docx'){const mammoth=await ResumeDocuments.mammoth();text=(await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()})).value}else throw Error('Choose a PDF, DOCX, or TXT file.');if(!text||text.trim().length<50)throw Error('Not enough text could be extracted. Scanned PDFs need OCR; paste your resume text instead.');if(text.length>30000)throw Error('This file exceeds 30,000 characters. Paste a shorter version.');return text}
let resumeUploadBusy=false;
async function readResumeFile(file){
 if(!file||resumeUploadBusy)return;
 if(typeof requireAccount==='function'&&!requireAccount())return;
 const owner=Account.user.id,epoch=Account.sessionEpoch,status=$('#file-status'),client=Account.client;
 const current=()=>Account.user?.id===owner&&Account.sessionEpoch===epoch;
 const inputs=document.querySelectorAll('#resume-file,#profile-resume-file');
 resumeUploadBusy=true;inputs.forEach(input=>input.disabled=true);
 if(status)status.textContent='Saving your original resume document…';
 let uploadedPath=null,saved=false;
 try{
  const mime=await ResumeDocuments.validate(file);if(!current())return;
  if(typeof showBusyAt==='function')showBusyAt('resume-upload-progress','Reading your resume','Your original document will be saved even if text extraction is unavailable.');
  let text='',extractionMessage='';
  try{text=await parseResumeFile(file);if(text.trim().length<100)throw Error('Not enough text was extracted for matching.');}catch(e){text='';extractionMessage=String(e.message||'Text extraction is unavailable.').slice(0,400);}
  if(!current())return;
  const ext=file.name.split('.').pop().toLowerCase(),path=owner+'/'+crypto.randomUUID()+'.'+ext;
  if(typeof showBusyAt==='function')showBusyAt('resume-upload-progress','Saving your original document','Uploading to your private account.');
  const result=await client.storage.from('account-resumes').upload(path,file,{contentType:mime,upsert:false});if(result.error)throw Error('Could not store your resume. Please try again.');
  uploadedPath=path;if(!current())return;
  const previous=savedResumeFile();
  const name=file.name.length>200?file.name.slice(0,180)+'….'+ext:file.name;
  workspaceLocal.setItem('proof-resume-file',JSON.stringify({path,name,size:file.size,type:mime,uploadedAt:new Date().toISOString(),extractionStatus:text?'ready':'unavailable',extractionMessage}));
  setMarketplaceResume(text);workspaceLocal.removeItem('proof-resume-editor');
  const report=text?ResumeEngine.review(text):null;
  if(report)workspaceLocal.setItem('proof-resume-report',JSON.stringify(report));else workspaceLocal.removeItem('proof-resume-report');
  resetResumeReview();resumeReport=report;
  await saveWorkspace();if(!current())return;saved=true;ResumeDocuments.reset();
  if(previous?.path)await client.storage.from('account-resumes').remove([previous.path]);
  render();const message=$('#file-status');if(message)message.textContent=text?'Original resume saved. You can preview it here and attach it to applications.':'Original resume saved and ready to share. Text extraction was unavailable; add matching text separately to use resume analysis.';
 }catch(e){if(current()){const message=$('#file-status');if(message)message.textContent=e.message||'Could not save your resume. Please try again.';}}
 finally{
  if(uploadedPath&&!saved&&!current())await client.storage.from('account-resumes').remove([uploadedPath]).catch(()=>{});
  resumeUploadBusy=false;inputs.forEach(input=>input.disabled=false);if(current()&&typeof clearBusyAt==='function')clearBusyAt('resume-upload-progress');
 }
}

function savedResumeFile(){try{return JSON.parse(workspaceLocal.getItem('proof-resume-file')||'null')}catch{return null}}
function savedResumeHTML(manage=false){const file=savedResumeFile(),hasText=Boolean((workspaceSession.getItem('proof-resume')||'').trim());if(!file&&!hasText)return '';return `<div class="notice"><b>${file?(file.textEdited?'Original upload: ':'Saved resume: ')+esc(file.name):'Saved resume text'}</b><p>${file?Math.ceil(file.size/1024)+' KB · ':''}${file?.textEdited?'Matching uses your edited resume text. This file is the original upload.':'Used across your account'}</p><div class="resume-actions">${file?`<button type="button" class="outline" onclick="downloadSavedResume()">${file.textEdited?'Download original upload':'Download resume'}</button>`:''}${manage?'<button type="button" class="outline" onclick="clearProfileResume()">Clear resume</button><button type="button" class="primary" onclick="chooseProfileResume()">Upload a new resume</button>':'<a class="outline" href="#profile">Manage resume in profile</a>'}</div></div>`;}
async function clearProfileResume(){saveProfileDraft();try{await clearResume()}catch{toast('Could not clear your resume. Please try again.')}}

async function downloadSavedResume(){const file=savedResumeFile();if(!file)return;const owner=Account.user?.id;try{const result=await Account.client.storage.from('account-resumes').download(file.path);if(Account.user?.id!==owner)return;if(result.error)throw result.error;const url=URL.createObjectURL(result.data),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{toast('Could not download your resume. Please try again.')}}

function loadResumeExample(){workspaceSession.removeItem('proof-selected-listing');$('#review-listing').value='';$('#review-job').readOnly=false;$('#review-job-title').readOnly=false;$('#selected-listing-summary').innerHTML='';$('#review-resume').value=`Alex Johnson\nalex@example.com | https://github.com/example\nEDUCATION\nBS Computer Science, 2026\nSKILLS\nJavaScript, React, HTML, CSS, Git, SQL\nPROJECTS\n- Built a React dashboard for 40 student volunteers to coordinate weekly community events.\n- Developed accessible forms and reduced incomplete submissions by 20% in a class usability study.\n- Worked on a customer analytics report using SQL.\nEXPERIENCE\n- Collaborated with a team of 4 students to launch a campus resource directory.\n- Presented research findings to a student advisory group.\n`;$('#review-job').value='Junior Frontend Developer\nRequired: React, JavaScript, TypeScript, HTML, CSS, Git, Testing, and Accessibility.\nBuild responsive interfaces, collaborate with designers, write unit tests, and communicate technical decisions.\nA degree in a relevant field or equivalent practical experience is welcome.';$('#review-job-title').value='Junior Frontend Developer';$('#review-resume').oninput();const details=document.getElementById('resume-matching-text');if(details)details.open=true;toast('Example loaded. Choose a review type, then run your review.')}
async function clearResume(){if(resumeUploadBusy){toast('Wait for the resume upload to finish.');return}const owner=Account.user?.id,epoch=Account.sessionEpoch;const file=savedResumeFile();if(file){const result=await Account.client.storage.from('account-resumes').remove([file.path]);if(result.error){toast('Could not delete your saved resume. Please try again.');return}}if(Account.user?.id!==owner||Account.sessionEpoch!==epoch)return;if(typeof ResumeDocuments!=='undefined')ResumeDocuments.reset();workspaceLocal.removeItem('proof-resume-file');workspaceLocal.removeItem('proof-resume-report');workspaceLocal.removeItem('proof-resume-editor');workspaceLocal.removeItem('proof-resume-versions');['proof-resume','proof-job','proof-job-title','proof-selected-listing'].forEach(k=>workspaceSession.removeItem(k));workspaceLocal.removeItem('proof-ai-endpoint');workspaceLocal.removeItem('lp-resume');if(typeof detected!=='undefined')detected=[];if(typeof resetResumeReview==='function')resetResumeReview();resumeReport=null;await saveWorkspace();render();toast('Resume cleared across your account')}
let resumeReviewSequence=0;
function resetResumeReview(){resumeReviewSequence++;resumeReviewState={busy:false,error:'',step:0};resumeReportTab='summary'}
async function runResumeReview(e){
 e.preventDefault();if(typeof Account!=='undefined'&&!Account.user){location.hash='login';return}if(resumeReviewState.busy)return;
 const resume=$('#review-resume').value.trim(),job=$('#review-job').value.trim(),jobTitle=$('#review-job-title').value.trim(),targetField=resumeTargetField(jobTitle);
 const error=$('#review-error');error.textContent='';if(resume.length<100){error.textContent='Your document is saved, but matching needs at least 100 characters of text. Open Extracted text for matching, or upload a text-based PDF.';const details=document.getElementById('resume-matching-text');if(details)details.open=true;return}if(job&&job.length<80){error.textContent='Add at least 80 characters from the job description.';return}
 const ai=$('#review-method').value==='ai',listing=getResumeListing(),owner=typeof Account!=='undefined'?Account.user?.id:null,request=++resumeReviewSequence;
 const current=()=>request===resumeReviewSequence&&(typeof Account==='undefined'||Account.user?.id===owner);
 workspaceSession.setItem('proof-resume',resume);workspaceSession.setItem('proof-job',job);workspaceSession.setItem('proof-job-title',jobTitle);
 resumeReviewState={busy:true,error:'',step:0};location.hash='resume/results';render();window.scrollTo(0,0);
 try{
  let report;
  if(ai){const base=resumeAPIBase(),session=(await Account.client.auth.getSession()).data.session;if(!current())return;if(!session)throw Error('Your session has expired. Sign in again.');
   const response=await fetch(base+'/api/resume',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify({resume,job:job?(jobTitle?jobTitle+'\n'+job:job):'',targetRole:jobTitle,listingId:listing?.id||null,field:listing?.cat||targetField||graduateProfile().field||'Development'}),signal:AbortSignal.timeout(55000)});
   try{report=await response.json()}catch{throw Error('The review service did not return a result. Please try again.')}
   if(!current())return;if(!response.ok)throw Error(report.error||'AI review could not be completed.');if(!Array.isArray(report.metrics)||!Array.isArray(report.improvements))throw Error('The review service returned an incomplete result. Please try again.');
  }else report=ResumeEngine.review(resume,job?(jobTitle?jobTitle+'\n'+job:job):'');
  if(!current())return;report.listingId=listing?.id||null;report.targetRole=jobTitle;
  if(!job&&!listing&&targetField){report.match={...ResumeEngine.compatibility(resume,{cat:targetField,tags:[],criteria:[]}),summary:'Resume contribution evidence against '+targetField+' foundations. These are coaching criteria, not employer requirements.'};report.fieldOnly=true}
  if(listing){const fit=ResumeEngine.compatibility(resume,listing);report.match={...fit,summary:'Nextwork Match beta combines listing criteria (75%) with field foundations (25%). Partial evidence earns half credit. Missing resume evidence does not mean you lack the skill.'}}else if(job&&typeof NextworkMatch!=='undefined'){report.match=NextworkMatch.description(resume,job,ResumeEngine.skills)}
  resumeReport=report;resumeReportTab='summary';workspaceLocal.setItem('proof-resume-report',JSON.stringify(report));resumeReviewState.step=2;if(location.hash==='#resume/results'||location.hash==='resume/results')render();
  await saveWorkspace();if(!current())return;resumeReviewState={busy:false,error:'',step:2};if(location.hash==='#resume/results'||location.hash==='resume/results'){render();window.scrollTo(0,0)}
 }catch(err){if(!current())return;resumeReviewState={busy:false,error:err.message||'Review failed. Please try again.',step:0};if(location.hash==='#resume/results'||location.hash==='resume/results')render()}
}
let resumeReportTab='summary';
function setResumeReportTab(tab){resumeReportTab=tab;if(resumeReport)$('#resume-results').innerHTML=reportHTML(resumeReport)}
function reportHTML(r){
 const score=n=>Number.isFinite(+n)?Math.max(0,Math.min(100,Math.round(+n))):0,list=x=>Array.isArray(x)?x:[],listing=r.listingId?getResumeListing(r.listingId):null;
 const tabs=[['summary','Summary'],...(r.match?[['match',r.fieldOnly?'Field fit':'Job fit']]:[]),['improve','Next steps']];if(!tabs.some(([key])=>key===resumeReportTab))resumeReportTab='summary';
 return `<div class="review-report-heading"><span class="section-label">${r.source==='ai'?'AI RESUME REVIEW':'RESUME EVIDENCE REVIEW'}</span><h1>${listing?esc(listing.title):r.targetRole?esc(r.targetRole)+' · resume review':'Your resume review'}</h1><p>${listing?esc(listing.c)+' · '+esc(listing.cat)+' · '+esc(listing.weeks):'Feedback on structure, clarity, and the experience your resume demonstrates.'}</p><div class="report-view-tabs" role="tablist" aria-label="Review results" onkeydown="resumeTabKey(event)">${tabs.map(([tab,label])=>`<button id="report-tab-${tab}" role="tab" data-report-tab="${tab}" aria-selected="${resumeReportTab===tab}" aria-controls="report-panel-${tab}" tabindex="${resumeReportTab===tab?0:-1}" onclick="setResumeReportTab('${tab}')">${label}</button>`).join('')}</div></div>${r.fallbackReason?`<div class="notice">${esc(r.fallbackReason)}</div>`:''}
 <section id="report-panel-summary" class="panel report-card report-overview" role="tabpanel" aria-labelledby="report-tab-summary" ${resumeReportTab==='summary'?'':'hidden'}><div class="report-overview-top"><div class="report-grade"><strong>${score(r.score)}<small>/100</small></strong><span>Resume health</span></div><div><h2>${score(r.score)>=75?'Your resume has a solid foundation':'Focus on clearer evidence of your work'}</h2><p>${esc(r.summary||'')}</p><small>${r.source==='ai'?'AI coaching estimate':'Text-based feedback'} · This is not an employer ATS score or a prediction of hiring success.</small></div></div>${resumeEditsHTML(r,2)}<div class="report-overview-grid"><div class="score-metrics">${list(r.metrics).map(m=>`<div><div class="progress-label"><b>${esc(m.name)}</b><strong>${score(m.score)}<small>/100</small></strong></div><div class="progress"><i style="width:${score(m.score)}%"></i></div><p>${esc(m.detail)}</p></div>`).join('')}</div><div class="report-strengths"><h3>What’s working</h3>${list(r.strengths).map(s=>`<p>${icon('check',15)}<span>${esc(s)}</span></p>`).join('')||'<p>Review the improvement plan for ways to make your experience more specific.</p>'}<button class="outline" onclick="setResumeReportTab('improve')">See recommended improvements ${icon('arrow',16)}</button></div></div></section>
 ${r.match?`<section id="report-panel-match" class="panel report-card" role="tabpanel" aria-labelledby="report-tab-match" ${resumeReportTab==='match'?'':'hidden'}><div class="match-report-summary"><div><strong>${r.match.score===null?'Manual review':score(r.match.score)+'%'}</strong><span>Overall evidence coverage</span></div>${r.match.jobScore!=null?`<div><strong>${score(r.match.jobScore)}%</strong><span>Project criteria · 75% weight</span></div><div><strong>${score(r.match.fieldScore)}%</strong><span>Field foundations · 25% weight</span></div>`:''}${listing?`<button class="primary" onclick="apply(${listing.id})">Apply to this project ${icon('arrow',16)}</button>`:''}</div>${r.match.method==='nextwork-evidencenet-v1'?'<button type="button" class="match-model-tag" onclick="showNextworkModel()">Nextwork Match · EvidenceNet v1 beta · How it works</button>':''}${evidenceChartHTML(r.match)}</section>`:''}
 <section id="report-panel-improve" class="panel report-card" role="tabpanel" aria-labelledby="report-tab-improve" ${resumeReportTab==='improve'?'':'hidden'}><div class="report-plan-heading"><h2>Your improvement plan</h2><span>${list(r.improvements).length} recommendations</span></div>${resumeEditorHTML(r)}<div class="report-improvement-list">${list(r.improvements).map((x,i)=>`<details ${i===0?'open':''}><summary><span class="improvement-number">${i+1}</span><span>${esc(x.title)}</span><b>${esc(x.priority||'Suggested')} priority</b>${icon('arrow',15)}</summary><p>${esc(x.detail)}</p></details>`).join('')||'<p>No major issues were identified. Ask a trusted reviewer to check accuracy and relevance.</p>'}</div>${list(r.rewrites).length?`<details class="report-rewrites"><summary>Suggested line edits <span>${list(r.rewrites).length}</span></summary>${list(r.rewrites).map(x=>`<div class="rewrite"><small>ORIGINAL</small><p>${esc(x.before)}</p><small>EDITING DIRECTION</small><p>${esc(x.after)}</p><small>${esc(x.note)}</small></div>`).join('')}</details>`:''}<div class="report-plan-actions"><a class="outline" href="#resume">${icon('resume',16)} Edit your resume</a><a class="primary" href="#explore">Find relevant project work ${icon('arrow',16)}</a></div></section>`;
}
function resumeTabKey(event){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...event.currentTarget.querySelectorAll('[data-report-tab]')],index=tabs.indexOf(document.activeElement),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;const tab=tabs[next].dataset.reportTab;setResumeReportTab(tab);document.getElementById('report-tab-'+tab)?.focus()}

function downloadResumeReport(){if(!resumeReport)return;const r=resumeReport,text=['NEXTWORK RESUME REVIEW',r.source==='ai'?'Free-tier AI review':'Free text checks',`Health score: ${r.score}/100 (not an ATS score)`,r.summary,...r.metrics.map(m=>`${m.name}: ${m.score}/100\n${m.detail}`),'STRENGTHS',...r.strengths,'IMPROVEMENTS',...r.improvements.map(x=>`${x.priority}: ${x.title}\n${x.detail}`),...(r.match?['JOB ALIGNMENT',r.match.summary,'Supported: '+r.match.matched.join(', '),'Partial: '+(r.match.partial||[]).join(', '),'Evidence gaps: '+r.match.missing.join(', '),...r.match.requirements.map(x=>`${x.text}\n${x.status}: ${x.evidence}${x.reason?"\n"+x.reason:""}${x.suggestion?"\nNext step: "+x.suggestion:""}`)]:[]),'SUGGESTED EDITS',...r.rewrites.map(x=>`${x.before}\n→ ${x.after}\n${x.note}`)].join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='nextwork-resume-review.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

async function checkResumeBackend(){
const status=$('#backend-status');if(!status)return;
const base=resumeAPIBase();
try{
const response=await fetch(base+'/api/resume',{signal:AbortSignal.timeout(8000)});if(!response.ok)throw Error('Backend unavailable');const state=await response.json();if(state.service!=='prooflane-resume')throw Error('Wrong backend');
status.textContent=state.aiConfigured?'Free-tier AI is available within its quota. Free on-device review is always available.':'Free on-device review is ready. Optional free-tier AI is not configured.';
// Keep free on-device review as the default; remote AI always requires an explicit choice.
}catch{status.textContent='AI server could not be reached. Local review is ready.'}
}

function getResumeListing(id=workspaceSession.getItem('proof-selected-listing')){return jobs.find(j=>j.id===Number(id))}
function listingDescription(j){return `${j.title}\nCompany: ${j.c} (${j.sector})\nEngagement: Paid fixed-scope contract project. Remote. Budget: $${j.pay}. Duration: ${j.weeks}.\nProject brief: ${j.desc}\nSkills requested: ${j.tags.join(', ')}.\nDeliverables: ${j.deliver}\nExpected impact: ${j.impact}${j.demoCreator?'\nProject context: '+j.demoCreator.context+'\nResponsibilities:\n'+j.demoCreator.responsibilities.map(t=>'- '+t).join('\n')+'\nDetailed handoff:\n'+j.demoCreator.deliverables.map(t=>'- '+t).join('\n')+'\nCollaboration: '+j.demoCreator.collaboration+'\nRelevant experience: '+j.demoCreator.fit:''}`}
function listingSummary(id=workspaceSession.getItem('proof-selected-listing'),result=false){const j=getResumeListing(id);if(!j)return '';return `<div class="selected-opportunity"><span class="tag">Sample marketplace listing</span><h3>${esc(j.title)}</h3><p>${esc(j.c)} · $${j.pay.toLocaleString()} · ${esc(j.weeks)} · Remote</p><p>Match feedback uses the skills, brief, and deliverables published on this listing.</p><a href="#project/${j.id}" class="text-link">${result?'View project & apply':'View full project'} ${icon('arrow',14)}</a>${result?`<button class="outline" style="margin-top:14px" onclick="apply(${j.id})">Apply to this project ${icon('arrow',14)}</button>`:''}</div>`}
function saveResumeDraft(){if($('#review-resume'))workspaceSession.setItem('proof-resume',$('#review-resume').value);if($('#review-job'))workspaceSession.setItem('proof-job',$('#review-job').value);if($('#review-job-title'))workspaceSession.setItem('proof-job-title',$('#review-job-title').value)}
function selectResumeListing(id){saveResumeDraft();resetResumeReview();const j=getResumeListing(id);resumeReport=null;if(j){workspaceSession.setItem('proof-selected-listing',j.id);workspaceSession.setItem('proof-job',listingDescription(j));workspaceSession.setItem('proof-job-title',j.title)}else{workspaceSession.removeItem('proof-selected-listing');workspaceSession.setItem('proof-job','');workspaceSession.setItem('proof-job-title','')}render()}
function matchListing(id){const j=getResumeListing(id);if(!j)return;resetResumeReview();if(location.hash==='#resume')saveResumeDraft();workspaceSession.setItem('proof-selected-listing',j.id);workspaceSession.setItem('proof-job',listingDescription(j));workspaceSession.setItem('proof-job-title',j.title);resumeMode='job';resumeReport=null;if(location.hash==='#resume')render();else location.hash='resume'}

function setMarketplaceResume(text){const previous=workspaceSession.getItem('proof-resume')||'';workspaceSession.setItem('proof-resume',text);if(previous!==text){sort='match';resetResumeReview();resumeReport=null;workspaceLocal.removeItem('proof-resume-report');}}

function resumeAPIBase(){return location.hostname==='nextwork-jobs.vercel.app'?'':'https://nextwork-jobs.vercel.app'}

async function cleanupResumeUploads(){
if(resumeUploadBusy)throw Error("Wait for your resume upload to finish before deleting the account.");
const owner=Account.user?.id;if(!owner)return;
// Include interrupted uploads as well as the current saved file.
for(;;){const result=await Account.client.storage.from('account-resumes').list(owner,{limit:100});if(result.error)throw result.error;const paths=result.data.filter(row=>row.id).map(row=>owner+'/'+row.name);if(!paths.length)return;const removed=await Account.client.storage.from('account-resumes').remove(paths);if(removed.error)throw removed.error;}
}

// Refresh the opportunity catalog without replacing a resume form someone is editing.
function refreshResumeListingOptions(){const select=$('#review-listing');if(!select)return;const value=select.value,previous=select.selectedOptions[0]?.textContent;select.innerHTML='<option value="">No listing selected</option>'+jobs.map(j=>`<option value="${j.id}">${esc(j.c)} · ${esc(j.title)}</option>`).join('')+(value&&!jobs.some(j=>String(j.id)===value)?`<option value="${esc(value)}">${esc(previous||'Previously selected opportunity')}</option>`:'');select.value=value;if(typeof enhanceSearchSelects==='function')enhanceSearchSelects()}

function resumeTargetField(value){const v=String(value||'').toLowerCase();if(/data|analytics|statistic|business intelligence|machine learning/.test(v))return 'Data & Analytics';if(/design|ux|ui\b|researcher/.test(v))return 'Design';if(/market|content|copywrit|growth|social media/.test(v))return 'Marketing';if(/develop|software|frontend|front.end|backend|back.end|devops|cloud|cyber/.test(v))return 'Development';if(/business|product manager|project manager|finance|financial|sales|operations|strategy/.test(v))return 'Business';return null}

function resumeEditSuggestions(report){const text=marketplaceResume(),drafts=ResumeEngine.improvementDrafts(text,workspaceSession.getItem('proof-job')||''),normalized=value=>String(value||'').replace(/\s+/g,' ').trim().toLowerCase();const ai=(report.source==='ai'&&Array.isArray(report.rewrites)?report.rewrites:[]).filter(x=>x.before&&normalized(text).includes(normalized(x.before))).map(x=>({title:'Refine this resume line',section:'From your review',before:x.before,draft:x.after,why:x.note||'Check this wording for accuracy before using it.'}));const completed=(graduateProfile().projects||[]).filter(p=>p.source==='nextwork-project'&&!normalized(text).includes(normalized(p.title))).slice(0,1).map(p=>({title:'Add your completed project',section:'Projects',before:'',draft:p.title+(p.url?' | '+p.url:'')+'\n• '+(p.description||'[Describe what you personally built, tested, or delivered].')+'\n• [Verified result or lesson from your project].',why:'This project is marked complete in your profile. Review the wording and fill any placeholders before adding it.'}));return [...completed,...ai,...drafts].slice(0,8)}
function resumeEditsHTML(report,limit=8){const all=resumeEditSuggestions(report),edits=all.slice(0,limit);return `<section class="resume-suggested-edits"><div class="resume-edits-heading"><div><span class="section-label">CONCRETE EDITS TO CONSIDER</span><h2>Here’s what you can add or change</h2></div><span>${edits.length} of ${all.length} suggestions</span></div><p>These are drafts. Replace every bracketed prompt with facts you can support.</p><div class="resume-edit-grid">${edits.map((edit,i)=>`<article class="resume-edit-card"><div class="resume-edit-title"><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(edit.title)}</h3><small>${esc(edit.section)}</small></div>${edit.before?`<div class="resume-edit-before"><small>CURRENT LINE</small><p>${esc(edit.before)}</p></div>`:''}<div class="resume-edit-draft"><small>${edit.before?'SUGGESTED EDIT':'SUGGESTED ADDITION'}</small><p>${esc(edit.draft)}</p></div><p class="resume-edit-reason">${esc(edit.why)}</p><button class="text-control" onclick="copyResumeEdit(${i})">${icon('link',14)} Copy draft</button></article>`).join('')}</div>${all.length>limit?`<button class="outline" onclick="setResumeReportTab('improve')">See all ${all.length} suggestions ${icon('arrow',15)}</button>`:''}</section>`}
function copyResumeEdit(index){const edit=resumeEditSuggestions(resumeReport||{})[index];if(!edit)return;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(edit.draft).then(()=>toast('Draft copied. Replace the bracketed prompts before using it.'),()=>toast('Copy is unavailable. Select the draft text to copy it.'));else toast('Select the draft text to copy it.')}
